We start by proving the following 2 auxiliary statements:

\begin{restatable} [Modification of {\cite[Lemma 8]{panteleev2021asymptotically}} or {\cite[Lemma 30]{leverrier2022quantum}}] {lemma}{RobustLemma} \label{lem:small-distance-is-structured}
  Suppose $C_A$ and $C_B$ have distance $d_1$.
  If $c \in \tensorcode(C_A, C_B)$ is supported on $I_a \times [n_b] \cup [n_a] \times I_b$
  and $|I_a|, |I_b| < d_1$,
  then there exists $c_a \in C_A \otimes \F2^{n_b}$ supported on $[n_a] \times I_b$ and $c_b \in \F2^{n_a} \otimes C_B$ supported on $I_a \times [n_b]$
  such that $c = c_a + c_b$.

  Furthermore, if $|I_a|, |I_b| < d_1/2$, we have
  \begin{equation*}
    \abs{c} \ge \frac{d_1}{2}(\norm{c_a}_{[n_b]} + \norm{c_b}_{[n_a]}).
  \end{equation*}
\end{restatable}
\begin{proof}[Proof of \Cref{lem:small-distance-is-structured}]
  The intuition is that one can construct $c_a$ using $c_{([n_a] - I_a) \times I_b}$ by requiring each column to be a codeword in $C_A$.
  Because each column is only missing $|I_a| < d_1$ values,   
    which is less than the distance,
    one can uniquely recover the codeword.
  This intuition is correct, but requires more steps to make it rigorous as we will do below.



  Let $H_A' = H_A|_{I_a}\colon \F2^{I_a} \to \F2^{m_a}$ be the restriction of $H_A$. 
  Because $C_A$ has distance $d_1$ and $|I_a| < d_1$, $H_A'$ is injective.
  Since $H_A'$ is an injective linear map, there exists (not unique) a left inverse linear map $J_A'\colon \F2^{m_a} \to \F2^{I_a}$, such that
  \begin{equation*}
    J_A' H_A' = I_{I_a}
  \end{equation*}
  where $I_{I_a}$ is the identity for $\F2^{I_a}$.
  Similarly, we can define $H_B'$ and $J_B'$.

  Using $J_A'$ we can explicitly write down a recovery map for the erased codeword.
  \begin{claim} \label{claim:vector-recover}
    For any codeword $v \in C_A \subset \F2^{n_a}$,
    one can recover $v$ from $v_{[n_a]-I_a}$ through the following linear map
    \begin{equation*}
      v = (J_A' H_A|_{[n_a]-I_a} \Vert I_{[n_a] - I_a}) v_{[n_a]-I_a}
    \end{equation*}
    where $\Vert$ is concatenation.
  \end{claim}
  Notice that $J_A' H_A|_{[n_a]-I_a} \colon \F2^{[n_a] - I_a} \to \F2^{I_a}$ and $I_{[n_a] - I_a} \colon \F2^{[n_a] - I_a} \to \F2^{[n_a] - I_a}$, so \\ $J_A' H_A|_{[n_a]-I_a} \Vert I_{[n_a] - I_a} \colon \F2^{[n_a] - I_a} \to \F2^{[n_a]}$.
  \begin{proof}[Proof of \Cref{claim:vector-recover}]
    Because $v \in C_A$ is a codeword, we have $H_A v = 0$,
    so $H_A' v_{I_a} = H_A|_{[n_a]-I_a} v_{[n_a]-I_a}$.
    Multiply both side by $J_A'$, we obtain $J_A' H_A' v_{I_a} = v_{I_a} = J_A' H_A|_{[n_a]-I_a} v_{[n_a]-I_a}$ which is the desired result.
  \end{proof}

  This suggests one can recover $c_a$ from $c_{([n_a]-I_a) \times I_b}$
    by mapping each column supported on $[n_a]-I_a$ to the full codeword supported on $[n_a]$.
  However, we need to first show each $c_{([n_a]-I_a) \times i_b}$ is a truncation of a codeword in $C_A$ which we will do now.
  Because $H_A H_B c = 0$, each column of $H_B c$ is a codeword in $C_A$.
  Because $J_B' H_B' = I_{I_b}$, $c_{([n_a]-I_a) \times I_b} = J_B' H_B' c_{([n_a]-I_a) \times I_b} = (J_B' (H_B c))|_{([n_a]-I_a) \times [m_b]}$,
    indeed each column of $c_{([n_a]-I_a) \times I_b}$ is a truncation of codeword.

  This leads to the following choice of $c_a$ and $c_b$
  \begin{equation*}
    c_a = ((J_A' H_A|_{[n_a] - I_a} \Vert I_{[n_a] - I_a}) c_{([n_a]-I_a) \times I_b}) \big\Vert 0_{[n_a] \times ([n_b] - I_b)}
  \end{equation*}
  and
  \begin{equation*}
    c_b = ((J_B' H_B|_{[n_b] - I_b} \Vert I_{[n_b] - I_b}) c_{I_a \times ([n_b]-I_b)}) \big\Vert 0_{([n_a] - I_a) \times [n_b]}.
    \end{equation*}

  By construction $c_a$ is supported on $[n_a] \times I_b$ and $c_b$ is supported on $I_a \times [n_b]$.
  And from the discussion we know $c_a \in C_A \otimes \F2^{n_b}$ and $c_b \in \F2^{n_a} \otimes C_B$.
  What is left to be shown is $c = c_a + c_b$.

  By construction we know $c$ agrees with $c_a + c_b$ on everywhere outside of $I_a \otimes I_b$,
  that is $c' \coloneqq c + c_a + c_b$ is supported on $I_a \otimes I_b$.
  Now, $H_B c'$ is supported on $I_a \otimes [m_b]$ and each column is a codeword in $C_A$ (because $H_A (H_B c') = 0$).
  Because the distance of $C_A$ is $d_1$ and $|I_a|<d_1$, we have $H_B c' = 0$.
  Similarly, $c'$ is supported on $I_a \otimes I_b$ and each row is a codeword in $C_B$ (because $H_B c' = 0$).
  Because the distance of $C_B$ is $d_1$ and $|I_b|<d_1$, we have $c' = 0$.
  This concludes the first half of the lemma.

  The second half is simple. 
  Since each column of $c_a$ is a codeword, it is either $0$ or has weight $\ge d_1$.
  For those with weight $\ge d_1$, after removing the indices in $I_a$ it still have weight $> d_1/2$.
  That is 
  \begin{equation*}
    \abs{c_{([n_a] - I_a) \times I_b}} \ge \frac{d_1}{2} \norm{c_a}_{[n_b]}.
  \end{equation*}
  Similarly,
  \begin{equation*}
    \abs{c_{I_a \times ([n_b] - I_b)}} \ge \frac{d_1}{2} \norm{c_b}_{[n_a]}.
  \end{equation*}
  So 
  \begin{equation*}
    \abs{c} \ge \frac{d_1}{2} (\norm{c_a}_{[n_b]} + \norm{c_b}_{[n_a]}).
  \end{equation*}
\end{proof}

\begin{lemma} \label{lem:large-distance-after-puncture}
  Fix $\rho_a, \rho_b \in (0,1)$, let $\sigma \in (0, 1), \tau \in (0, (1-\sigma)/2)$ satisfy
  \begin{equation*}
    2 h(\sigma) + 2 (1-\sigma)h(\frac{\tau}{1-\sigma}) < \frac{3}{4} \frac{(1 - \sigma - \rho_a)(1 - \sigma - \rho_b)}{1-\sigma}.
  \end{equation*}
  Let $C_A, C_B$ be random codes sampled from the uniform distribution with length $\Delta$ and dimensions $k_a=\rho_a \Delta, k_b=\rho_b \Delta$.
  Then as $\Delta$ goes to infinity, with probability tending to $1$, the following holds:
    for any $s = \sigma \Delta$-punctured code $C_A', C_B'$,
    all non-zero codewords in $\tensorcode(C_A', C_B')$ have at least one row or one column with weight $\ge t = \tau \Delta$.
  In other words, if a codeword in $\tensorcode(C_A', C_B')$ has all its rows and columns with weight $< t$, then the codeword is $0$.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:large-distance-after-puncture}]

  To show the lemma, we apply the union bound over the bad events.
  First, there are $\binom{\Delta}{s}^2$ possible $s$-punctured code pairs $C_A', C_B'$ when puncturing both $C_A$ and $C_B$.
  Next, there are $\abs{\cM(\Delta-s, r, t)}$ many rank $r$ matrices where all rows and columns have weight $<t$.
  Finally, each of those rank $r$ matrix is a codeword with probability $\le \cP(\Delta-s, r, k_a, k_b)$ which we explain below.
  Recall that $C_A$ is a uniform distribution over dimension $k_a$,
    so $C_A'$ is a mixture of uniform distribution over dimensions $k'_a \le k_a$.
  Suppose $C_A'$($C_B'$) has dimension $k'_a$($k'_b$) with probability $p_{k'_a}$($q_{k'_b}$),
    then a rank $r$ matrix is a codeword with probability $\le \sum_{k'_a=0}^{k_a} \sum_{k'_b=0}^{k_b} p_{k'_a} q_{k'_b} \cP(\Delta-s, r, k'_a, k'_b)$.
  Because smaller dimension leads to smaller probability of becoming a codeword, $\cP(\Delta-s, r, k'_a, k'_b) \le \cP(\Delta-s, r, k_a, k_b)$,
    the probability for a rank $r$ matrix to be a codeword $\le \cP(\Delta-s, r, k_a, k_b)$ as claimed.

  Therefore, the probability where the main condition fails to hold (there are some $s$-punctured code pair $C'_A, C'_B$ with non-zero codeword in $\tensorcode(C_A', C_B')$
  where all its rows and columns has weight $< t$) is
  \begin{align*}
    &\le \binom{\Delta}{s}^2 \sum_{r=1}^{\Delta-s} \abs{\cM(\Delta-s, r, t)}\, \cP(\Delta-s, r, k_a, k_b) \\
    &\le 2^{2 \Delta h(\frac{s}{\Delta})} \cdot 
      \sum_{r=1}^{\Delta-s} 2^{2r(\Delta-s) h(\frac{t}{\Delta-s}) + 2(\Delta-s) h(\frac{r}{\Delta-s})} \cdot
      512 (r+1) 2^{-\frac{3}{4} \frac{(\Delta-s-k_a) (\Delta-s-k_b)}{\Delta-s} r}
  \end{align*}
  where the last inequality uses $\binom{\Delta}{s} \le 2^{\Delta h(\frac{s}{\Delta})}$ and the results from \Cref{claim:number-of-bad-matrix-is-small} and \Cref{claim:bad-matrix-is-likely-not-codeword}.

  Finally, we find the requirements for the value to approach $0$ as $\Delta$ goes to infinity.
  This boils down to two conditions.
  The first is 
    \begin{equation*}
      2 \frac{\Delta - s}{\Delta} h(\frac{t}{\Delta-s}) < \frac{3}{4} \frac{(\Delta - s - k_a)(\Delta - s - k_b)}{\Delta (\Delta - s)}
    \end{equation*}
    so that large $r$ has exponentially decaying contribution.
  The second is 
    \begin{equation*}
      2h(\frac{s}{\Delta}) + 2\frac{\Delta-s}{\Delta} h(\frac{t}{\Delta-s}) < \frac{3}{4} \frac{(\Delta - s - k_a)(\Delta - s - k_b)}{\Delta (\Delta - s)}
    \end{equation*}
    so that the contribution for $r=1$ approaches $0$.
  It is clear that we can reduce the two inequalities to just the second one.
  By rewriting the variables $s = \sigma \Delta, t = \tau \Delta, k_a = \rho_a \Delta, k_b = \rho_b \Delta$, we see that if
    \begin{equation*}
      2 h(\sigma) + 2 (1-\sigma)h(\frac{\tau}{1-\sigma}) < \frac{3}{4} \frac{(1 - \sigma - \rho_a)(1 - \sigma - \rho_b)}{1-\sigma}
    \end{equation*}
    as $\Delta$ goes to infinity, with probability tending to $1$,
    for any $s = \sigma \Delta$-punctured code $C_A', C_B'$,
    all non-zero codewords in $\tensorcode(C_A', C_B')$ have at least one row or one column with weight $\ge t = \tau \Delta$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}[Proof of \Cref{thm:random-tensor-codes-are-robust}]
  We first show linear distance. The \Cref{eq:GV-2d} in the theorem statement implies $h(\delta_1) < 1 - \rho_a$ and $h(\delta_1) < 1 - \rho_b$ because $h(\delta_1) < 2 h(\delta_1/2)$ for $\delta_1 < 1/2$.
  By Gilbert-Varshamov bound, we know $C_A, C_B$ have distance $d_1 = \delta_1 \Delta$ with probability tending to $1$.

  Next, we prove that $(C_A,C_B)$ is $\delta_2 \Delta$-robust when $C_A, C_B$ have distance $d_1$ and the condition in \Cref{lem:large-distance-after-puncture} holds.
  More precisely, because the inequality in \Cref{lem:large-distance-after-puncture} holds for $\sigma = \delta_1/2$ and $\tau = 4 \delta_2/\delta_1$,
  we have that for all $s = \sigma \Delta$-punctured codes $C_A', C_B'$, if a codeword in $\tensorcode(C_A', C_B')$ has all columns and rows with weight $< t = \tau \Delta$,
  then the codeword is $0$.
  Note that the same holds for all punctured codes $C_A', C_B'$ with puncture $\le s$.


  Given $c \in \tensorcode(C_A, C_B)$, we consider the following two cases. First, assume that $c$ has small weight $|c| < d_1 t / 2$. We can remove $d_1/2-1=s-1$ columns $I_a$ and $s-1$ rows $I_b$ such that $c_{([n_a]-I_a)\times([n_b]-I_b)}$ has weight less than $t$ for each column and each row. 
  By \Cref{lem:large-distance-after-puncture}, 
    $c_{([n_a]-I_a)\times([n_b]-I_b)}$ has to be $0$.
  So $c$ is supported on at most $s-1$ columns and $s-1$ rows. 
  Now, because $s - 1 < s = d_1/2$, by \Cref{lem:small-distance-is-structured}
    \begin{equation*}
      \abs{c} \ge \frac{d_1}{2} (\norm{c_a}_{[n_b]} + \norm{c_b}_{[n_a]}).
    \end{equation*}

  Second, suppose $c$ has large weight $|c| \ge d_1 t / 2$. 
  Because $c \in \tensorcode(C_A, C_B)$, we can always write $c = c_a + c_b$. 
  For any choice of $c_a, c_b$, we have $\norm{c_a}_{[n_b]} + \norm{c_b}_{[n_a]} \le 2 \Delta$.
  Together with the fact that $c$ has large weight, we have
    \begin{equation*}
      \abs{c} \ge \frac{d_1 t}{4 \Delta} (\norm{c_a}_{[n_b]} + \norm{c_b}_{[n_a]}).
    \end{equation*}

  Therefore, the code pair $(C_A, C_B)$ is $\min(\frac{d_1}{2}, \frac{d_1 t}{4 \Delta}) = \frac{d_1 t}{4 \Delta} = \delta_2 \Delta$ robust.
\end{proof}
